{"code": "import pandas as pd, numpy as np, statsmodels.formula.api as smf
df = pd.read_csv('data/explore.csv')
# per-lab slopes for humidity and cure_hours
for c in ['humidity','cure_hours','press_time','carbon_pct']:
    print(c)
    for lab,g in df.groupby('lab'):
        m=smf.ols(f"tensile_mpa ~ {c}",data=g).fit()
        print(f"  {lab}: slope={m.params[c]: .3f} p={m.pvalues[c]:.3f}")
"}
